class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

def to_list(head):
    result = []
    current = head
    while current is not None:
        result.append(current.value)
        current = current.next
    return result

head = Node(10, Node(20, Node(30)))
print(to_list(head))

class Node:
    def __init__(self, value, next=None):
        self.value, self.next = value, next

def prepend(head, value):
    return Node(value, head)

def delete_first(head, target):
    dummy = Node(None, head)
    previous = dummy
    while previous.next is not None:
        if previous.next.value == target:
            previous.next = previous.next.next
            break
        previous = previous.next
    return dummy.next

head = prepend(None, 20)
head = prepend(head, 10)
head = delete_first(head, 10)
print(head.value)

class Node:
    def __init__(self, value, next=None):
        self.value, self.next = value, next

def middle(head):
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
    return slow

def has_cycle(head):
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

head = Node(4, Node(5, Node(6)))
print(middle(head).value, has_cycle(head))
